import json
import pathlib

from obligations import extract_obligations

AGREEMENT = (pathlib.Path(__file__).parent / "agreement.txt").read_text(encoding="utf-8")


def test_exact_extraction():
    assert extract_obligations(AGREEMENT) == [
        {
            "party": "Vendor",
            "modal": "shall",
            "sentence": 'Vendor shall deliver the Software within thirty days of the Effective Date.',
        },
        {
            "party": "Customer",
            "modal": "must",
            "sentence": "Customer must pay each invoice within fifteen days of receipt.",
        },
        # one sentence, two modals -> two entries
        {
            "party": "Vendor",
            "modal": "shall",
            "sentence": "The Vendor shall provide support during business hours, and shall remediate verified defects within five days.",
        },
        {
            "party": "Vendor",
            "modal": "shall",
            "sentence": "The Vendor shall provide support during business hours, and shall remediate verified defects within five days.",
        },
        # alias only AFTER the modal -> UNATTRIBUTED
        {
            "party": "UNATTRIBUTED",
            "modal": "must",
            "sentence": "All deliverables must be approved by Customer within ten days of submission.",
        },
        # no alias at all -> UNATTRIBUTED
        {
            "party": "UNATTRIBUTED",
            "modal": "shall",
            "sentence": "This Agreement shall be governed by the laws of Delaware.",
        },
        {
            "party": "Vendor",
            "modal": "shall",
            "sentence": "Vendor shall maintain professional liability insurance throughout the Term.",
        },
        {
            "party": "Customer",
            "modal": "shall",
            "sentence": "Customer shall designate a single point of contact for escalations.",
        },
        # closest alias BEFORE the modal is Vendor, even though Customer follows
        {
            "party": "Vendor",
            "modal": "must",
            "sentence": "Vendor must notify Customer of any data breach within forty-eight hours.",
        },
        {
            "party": "Vendor",
            "modal": "shall",
            "sentence": "The Vendor shall not subcontract its duties without prior written consent.",
        },
        # second 'and must' sentence -> two entries
        {
            "party": "Customer",
            "modal": "must",
            "sentence": "Customer must provide timely access to facilities, and must supply accurate technical requirements.",
        },
        {
            "party": "Customer",
            "modal": "must",
            "sentence": "Customer must provide timely access to facilities, and must supply accurate technical requirements.",
        },
        # 'shallow' contains 'shall' as a substring but must NOT produce a match;
        # only the real 'shall' earlier in the sentence is extracted
        {
            "party": "Vendor",
            "modal": "shall",
            "sentence": "Vendor shall treat shallow acceptance results as advisory only.",
        },
    ]


def test_shallow_never_matches():
    entries = extract_obligations("shallow obligations are void.")
    assert entries == []


def test_word_boundary_modals():
    text = "Vendor shall perform. The team mustered effort. shallow waters."
    entries = extract_obligations(text)
    assert [(e["party"], e["modal"]) for e in entries] == [("Vendor", "shall")]


def test_cli_json_output(tmp_path):
    import subprocess
    import sys

    out = subprocess.run(
        [sys.executable, str(pathlib.Path(__file__).parent / "obligations.py"),
         str(pathlib.Path(__file__).parent / "agreement.txt")],
        capture_output=True, text=True, check=True,
    )
    parsed = json.loads(out.stdout)
    assert parsed == extract_obligations(AGREEMENT)
    assert len(parsed) == 13

